// Browser presentation only. The tracked-file manifest is generated by Elixir.
const esc = s => String(s ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const folderRank = name => ({lib:0,assets:1,priv:2,config:3,apps:4,scripts:5,test:6,tests:6,docs:7}[name] ?? (name.startsWith('.')?20:10));

export function createFileBrowser({host, manifest, byId, detail, selectFile, selectEntity, openEntity, filterChanged=()=>{}}) {
  let query='', category='', currentFile='', lens='architecture', token=0;
  const files=manifest.repositories.flatMap(r=>r.files), fileMap=new Map(files.map(f=>[f.id,f]));
  const expanded=new Set(manifest.repositories.map(r=>r.id));
  for(const r of manifest.repositories){expanded.add(`${r.id}/lib`);expanded.add(`${r.id}/apps`)}
  const fileIcon=f=>({ex:'elixir',exs:'elixir',js:'javascript',mjs:'javascript',py:'python',sh:'bash'}[f.name.split('.').pop()]);
  host.innerHTML=`<div class="file-browser"><section class="file-tree-pane" aria-label="Repository files"><div class="file-tree-tools"><input id="file-filter" type="search" placeholder="Filter files or modules…" aria-label="Filter repository files"><select id="file-category" aria-label="Filter file category"><option value="">All file categories</option>${[...new Set(files.map(f=>f.category))].sort().map(x=>`<option>${esc(x)}</option>`).join('')}</select><div class="tree-commands"><span id="file-match-count"></span><button id="collapse-folders">Collapse folders</button></div></div><div id="repository-tree" class="repository-tree" aria-label="Repository file tree"></div></section><section class="file-detail-pane" aria-label="File contents and symbols"><div id="file-detail"></div></section></div>`;
  const tree=host.querySelector('#repository-tree'), content=host.querySelector('#file-detail');
  function drawTree(){
    const words=query.toLowerCase().trim().split(/\s+/).filter(Boolean);
    const matches=files.filter(f=>(!category||f.category===category)&&words.every(w=>(f.path+' '+f.repo+' '+f.modules.map(id=>byId(id)?.full||'').join(' ')).toLowerCase().includes(w)));
    host.querySelector('#file-match-count').textContent=`${matches.length.toLocaleString()} / ${files.length.toLocaleString()} files`;
    function folder(node,key,depth=0){
      const dirs=[...node.dirs].sort(([a],[b])=>folderRank(a)-folderRank(b)||a.localeCompare(b));
      return dirs.map(([name,child])=>{
        const k=key+'/'+name, open=query||category||expanded.has(k);
        return `<details data-folder="${esc(k)}" ${open?'open':''}><summary><span class="folder-name">${esc(name)}</span><small>${child.count}</small></summary><div class="tree-children">${folder(child,k,depth+1)}</div></details>`;
      }).join('')+node.files.sort((a,b)=>a.name.localeCompare(b.name)).map(f=>{
        const lang=fileIcon(f);return `<button class="tree-file ${currentFile===f.id?'selected':''}" data-file="${esc(f.id)}" title="${esc(f.path)}" aria-label="Open ${esc(f.repo+'/'+f.path)}" ${currentFile===f.id?'aria-current="true"':''}><span class="file-glyph">${lang?`<img src="assets/${lang}.svg" alt="">`:'▧'}</span><span>${esc(f.name)}</span>${f.functions?`<small>${esc(f.functions)}</small>`:''}</button>`;
      }).join('');
    }
    tree.innerHTML=manifest.repositories.map(repo=>{
      const fs=matches.filter(f=>f.repo===repo.id);if(!fs.length)return '';
      const root={dirs:new Map(),files:[],count:fs.length};
      for(const f of fs){let n=root;for(const part of f.path.split('/').slice(0,-1)){if(!n.dirs.has(part))n.dirs.set(part,{dirs:new Map(),files:[],count:0});n=n.dirs.get(part);n.count++}n.files.push(f)}
      return `<details class="repo-root" data-folder="${esc(repo.id)}" ${query||category||expanded.has(repo.id)?'open':''}><summary><span class="repo-symbol">▣</span><strong>${esc(repo.id)}</strong><small>${fs.length}</small></summary><div class="tree-children">${folder(root,repo.id)}</div></details>`;
    }).join('')||'<p class="empty-state">No matching files. Clear the search or choose another category.</p>';
    for(const el of tree.querySelectorAll('details'))el.addEventListener('toggle',()=>{if(el.open)expanded.add(el.dataset.folder);else expanded.delete(el.dataset.folder)});
  }
  async function showFile(id){
    const t=++token, f=fileMap.get(id);currentFile=id;
    if(!f){content.innerHTML='<div class="file-welcome"><span>▱</span><h2>Browse your repositories</h2><p>Choose a file from the tree. Open its functions here, then explore relationships when you need the graph.</p><div class="note">All tracked files are available. Function extraction covers a subset; configuration, templates, tests and docs remain visible.</div></div>';return}
    content.innerHTML=`<div class="file-heading"><div class="file-path">${esc(f.repo)} / ${esc(f.path)}</div><h2>${esc(f.name)}</h2><div class="file-tags"><span class="badge">${esc(f.category)}</span><span class="badge gray">${f.modules.length} indexed modules · ${esc(f.functions)} functions</span></div><a href="${esc(f.url)}" target="_blank" rel="noreferrer">Open source at snapshot revision ↗</a></div><div id="file-symbols"><p class="empty-state">Loading symbols…</p></div>`;
    try{
      const details=await Promise.all(f.modules.map(id=>detail(byId(id))));if(t!==token)return;
      host.querySelector('#file-symbols').innerHTML=f.modules.length?details.map((d,i)=>{
        const m=byId(f.modules[i]);return `<section class="file-module"><div class="file-module-heading"><div><small>MODULE</small><h3>${esc(m.full)}</h3></div><button class="secondary" data-module-graph="${esc(m.id)}">Open graph ↗</button></div>${Object.values(d.functions).sort((a,b)=>a.line-b.line).map(fn=>`<button class="symbol-row" data-symbol="${esc(fn.id)}"><span class="function-glyph">ƒ</span><strong>${esc(byId(fn.id).label)}</strong><small>${esc(fn.kind)} · line ${esc(fn.line)}</small><span>→</span></button>`).join('')}</section>`;
      }).join(''):'<div class="note">This file is tracked in the repository but has no indexed function details. It may be configuration, a template, a test, documentation, an asset, or outside the extraction scope. Use the source link to read it.</div>';
    }catch(error){if(t===token)host.querySelector('#file-symbols').textContent=error.message}
  }
  host.querySelector('#file-filter').oninput=e=>{query=e.target.value;drawTree();filterChanged(query)};
  host.querySelector('#file-category').onchange=e=>{category=e.target.value;drawTree()};
  host.querySelector('#collapse-folders').onclick=()=>{expanded.clear();manifest.repositories.forEach(r=>expanded.add(r.id));drawTree()};
  host.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.file){selectFile(fileMap.get(b.dataset.file))}else if(b.dataset.symbol){selectEntity(b.dataset.symbol)}else if(b.dataset.moduleGraph){openEntity(b.dataset.moduleGraph)}});
  function reveal(id){const f=fileMap.get(id);if(!f)return;expanded.add(f.repo);let key=f.repo;for(const p of f.path.split('/').slice(0,-1)){key+='/'+p;expanded.add(key)}}
  return {files,fileMap,filterRepository(repo){category='';host.querySelector('#file-category').value='';query=repo;host.querySelector('#file-filter').value=repo;drawTree()},async update({file,selected,filter=''}){const changed=currentFile!==file,filterUpdated=query!==filter;if(filterUpdated){query=filter;host.querySelector('#file-filter').value=filter;drawTree()}reveal(file);const scroll=tree.scrollTop;if(changed){await showFile(file);drawTree()}else if(!tree.children.length||!content.children.length){drawTree();await showFile(file)}tree.scrollTop=scroll;tree.querySelectorAll('[data-file]').forEach(b=>{const active=b.dataset.file===file;b.classList.toggle('selected',active);if(active)b.setAttribute('aria-current','true');else b.removeAttribute('aria-current')});host.querySelectorAll('[data-symbol]').forEach(b=>b.classList.toggle('selected',b.dataset.symbol===selected))}};
}
